/**
 * API Service — HTTP requests (mirrors React Native ApiService)
 */

import { API_BASE_URL } from '../utils/constants';

export const NETWORK_UNAVAILABLE_MESSAGE = 'App requires Internet to run';

function isNetworkFailure(error) {
  if (error == null) return false;
  const msg = error instanceof Error ? error.message : String(error);
  const m = msg.toLowerCase();
  return (
    m === 'network request failed' ||
    m.includes('networkerror') ||
    m.includes('failed to fetch') ||
    m.includes('network request failed') ||
    m.includes('the internet connection appears to be offline') ||
    m.includes('network is unreachable') ||
    m.includes('could not connect') ||
    m.includes('connection refused') ||
    m.includes('timed out') ||
    m.includes('timeout') ||
    m.includes('host could not be found') ||
    m.includes('name not resolved')
  );
}

function parseResponseBody(text, status, ok) {
  const trimmed = text.trim();
  if (!trimmed) {
    return {};
  }
  try {
    return JSON.parse(trimmed);
  } catch {
    const preview = trimmed.length > 160 ? `${trimmed.slice(0, 160)}…` : trimmed;
    throw new Error(
      ok
        ? `Invalid response (not JSON). ${preview}`
        : `Request failed (${status}). Response was not JSON. ${preview}`
    );
  }
}

class ApiService {
  constructor() {
    this.baseURL = API_BASE_URL;
    this.token = null;
  }

  setToken(token) {
    this.token = token;
  }

  getToken() {
    return this.token;
  }

  async request(endpoint, options = {}) {
    const url = `${this.baseURL}${endpoint}`;
    const headers = {
      'Content-Type': 'application/json',
      ...(options.headers || {}),
    };

    if (this.token) {
      headers.Authorization = `Bearer ${this.token}`;
    }

    try {
      const response = await fetch(url, {
        ...options,
        headers,
      });

      const text = await response.text();
      const data = parseResponseBody(text, response.status, response.ok);

      if (!response.ok) {
        const msg =
          (typeof data === 'object' &&
            data !== null &&
            'message' in data &&
            typeof data.message === 'string' &&
            data.message) ||
          `Request failed with status ${response.status}`;
        throw new Error(msg);
      }

      return data;
    } catch (error) {
      if (isNetworkFailure(error)) {
        throw new Error(NETWORK_UNAVAILABLE_MESSAGE);
      }

      console.error('API Request Error:', {
        url,
        error: error instanceof Error ? error.message : error,
      });

      throw error;
    }
  }

  async post(endpoint, body) {
    return this.request(endpoint, {
      method: 'POST',
      body: JSON.stringify(body),
    });
  }

  async get(endpoint) {
    return this.request(endpoint, {
      method: 'GET',
    });
  }

  async put(endpoint, body) {
    return this.request(endpoint, {
      method: 'PUT',
      body: JSON.stringify(body),
    });
  }

  async delete(endpoint) {
    return this.request(endpoint, {
      method: 'DELETE',
    });
  }
}

export default new ApiService();
