import Vue from 'vue';
import VueRouter from 'vue-router';
import store from '../store';

Vue.use(VueRouter);

const Login = () => import('../views/Login.vue');
const Register = () => import('../views/Register.vue');
const MainLayout = () => import('../layouts/MainLayout.vue');
const DriverHome = () => import('../views/DriverHome.vue');
const PendingOrders = () => import('../views/PendingOrders.vue');
const OngoingOrders = () => import('../views/OngoingOrders.vue');

const routes = [
  {
    path: '/login',
    name: 'Login',
    component: Login,
    meta: { guest: true },
  },
  {
    path: '/register',
    name: 'Register',
    component: Register,
    meta: { guest: true },
  },
  {
    path: '/',
    component: MainLayout,
    meta: { requiresAuth: true },
    children: [
      {
        path: '',
        redirect: { name: 'DriverHome' },
      },
      {
        path: 'home',
        name: 'DriverHome',
        component: DriverHome,
        meta: {
          title: 'Naija Meals',
          showBack: false,
          showLogout: true,
        },
      },
      {
        path: 'pending',
        name: 'PendingOrders',
        component: PendingOrders,
        meta: {
          title: 'New Orders',
          showBack: true,
          showLogout: false,
        },
      },
      {
        path: 'ongoing',
        name: 'OngoingOrders',
        component: OngoingOrders,
        meta: {
          title: 'Ongoing Orders',
          showBack: true,
          showLogout: false,
        },
      },
    ],
  },
];

const router = new VueRouter({
  // Hash mode: no HTTP server needed; works with file:// and embedded WebViews (#/login, #/home, …)
  mode: 'hash',
  routes,
});

router.beforeEach((to, from, next) => {
  const isAuthenticated = store.getters['auth/isAuthenticated'];

  if (to.matched.some((r) => r.meta.requiresAuth) && !isAuthenticated) {
    next({ name: 'Login' });
    return;
  }

  if (to.meta.guest && isAuthenticated) {
    next({ name: 'DriverHome' });
    return;
  }

  next();
});

export default router;
