/**
 * Notification Service — web FCM stub + backend token sync (mirrors RN API surface)
 * Full Firebase Web push requires VAPID / service worker; token sync matches RN behavior.
 */

import ApiService from './api';

class NotificationService {
  constructor() {
    this.notificationHandler = null;
  }

  async requestNotificationPermission() {
    if (!('Notification' in window)) {
      return false;
    }
    if (Notification.permission === 'granted') {
      return true;
    }
    if (Notification.permission === 'denied') {
      return false;
    }
    const result = await Notification.requestPermission();
    return result === 'granted';
  }

  /**
   * Web: no FCM token without Firebase SDK + config; returns null (registerTokenWithBackend no-ops).
   * Replace with firebase/messaging getToken when you add Firebase web config.
   */
  async getFCMToken() {
    return null;
  }

  async registerTokenWithBackend() {
    const token = await this.getFCMToken();
    if (!token) {
      console.warn('FCM: no token to register (web: add Firebase Messaging for push)');
      return;
    }
    await ApiService.put('/driver/fcm-token', { fcm_token: token });
  }

  async initialize() {
    // Foreground FCM would use firebase.messaging().onMessage here
    await this.requestNotificationPermission().catch(() => {});
  }

  vibrate(pattern = [0, 500, 200, 500]) {
    if (navigator.vibrate) {
      navigator.vibrate(pattern);
    }
  }

  playNotificationSound() {
    console.log('Notification sound (use system/FCM channel on device)');
  }

  setNotificationHandler(handler) {
    this.notificationHandler = handler;
  }

  triggerNotificationHandler(data) {
    if (this.notificationHandler) {
      this.notificationHandler(data);
    }
  }
}

export default new NotificationService();
