import NotificationService from '../../services/notification';

const state = {
  currentOrder: null,
  showOrderModal: false,
};

const mutations = {
  SET_CURRENT_ORDER(state, order) {
    state.currentOrder = order;
  },
  SET_SHOW_ORDER_MODAL(state, show) {
    state.showOrderModal = show;
  },
};

const actions = {
  async initNotifications({ dispatch }) {
    try {
      await NotificationService.initialize();
      NotificationService.setNotificationHandler((data) => {
        if (data.type === 'new_order') {
          dispatch('handleNewOrder', data);
        }
      });
    } catch (error) {
      console.error('Error initializing notifications:', error);
    }
  },

  handleNewOrder({ commit }, data) {
    const orderData = {
      type: data.type || 'new_order',
      restaurant_name: data.restaurant_name || 'Unknown Restaurant',
      restaurant_address: data.restaurant_address || 'Unknown Address',
      delivery_price: data.delivery_price || '0.00',
      order_id: data.order_id,
    };
    commit('SET_CURRENT_ORDER', orderData);
    commit('SET_SHOW_ORDER_MODAL', true);
    NotificationService.vibrate();
    NotificationService.playNotificationSound();
  },

  acceptOrder({ commit }) {
    console.log('Order accepted');
    commit('SET_SHOW_ORDER_MODAL', false);
    commit('SET_CURRENT_ORDER', null);
  },

  rejectOrder({ commit }) {
    console.log('Order rejected');
    commit('SET_SHOW_ORDER_MODAL', false);
    commit('SET_CURRENT_ORDER', null);
  },

  setShowOrderModal({ commit }, show) {
    commit('SET_SHOW_ORDER_MODAL', show);
  },
};

export default {
  namespaced: true,
  state,
  mutations,
  actions,
};
