/**
 * Authentication Service — mirrors React Native AuthService (localStorage)
 */

import ApiService from './api';

const TOKEN_KEY = '@driver_token';
const USER_KEY = '@driver_user';

class AuthService {
  async register(data) {
    const response = await ApiService.post('/driver/register', data);

    if (response.success && response.token && response.user) {
      await this.saveToken(response.token);
      await this.saveUser(response.user);
      ApiService.setToken(response.token);
      return { user: response.user, token: response.token };
    }

    throw new Error(response.message || 'Registration failed');
  }

  async login(data) {
    const response = await ApiService.post('/driver/login', data);

    if (response.success && response.token && response.user) {
      await this.saveToken(response.token);
      await this.saveUser(response.user);
      ApiService.setToken(response.token);
      return { user: response.user, token: response.token };
    }

    throw new Error(response.message || 'Login failed');
  }

  async logout() {
    try {
      await ApiService.post('/driver/logout', {});
    } catch (error) {
      console.error('Logout error:', error);
    } finally {
      await this.clearStorage();
      ApiService.setToken(null);
    }
  }

  async isLoggedIn() {
    const token = await this.getToken();
    return token !== null;
  }

  async getToken() {
    try {
      return localStorage.getItem(TOKEN_KEY);
    } catch (error) {
      console.error('Error getting token:', error);
      return null;
    }
  }

  async getUser() {
    try {
      const userJson = localStorage.getItem(USER_KEY);
      return userJson ? JSON.parse(userJson) : null;
    } catch (error) {
      console.error('Error getting user:', error);
      return null;
    }
  }

  async saveToken(token) {
    try {
      localStorage.setItem(TOKEN_KEY, token);
    } catch (error) {
      console.error('Error saving token:', error);
    }
  }

  async saveUser(user) {
    try {
      localStorage.setItem(USER_KEY, JSON.stringify(user));
    } catch (error) {
      console.error('Error saving user:', error);
    }
  }

  async clearStorage() {
    try {
      localStorage.removeItem(TOKEN_KEY);
      localStorage.removeItem(USER_KEY);
    } catch (error) {
      console.error('Error clearing storage:', error);
    }
  }

  async initializeAuth() {
    const token = await this.getToken();
    const user = await this.getUser();

    if (token) {
      ApiService.setToken(token);
    }

    return { token, user };
  }

  async toggleOnlineStatus(latitude, longitude) {
    const payload = {};

    if (latitude !== undefined && longitude !== undefined) {
      payload.latitude = latitude;
      payload.longitude = longitude;
    }

    const response = await ApiService.put('/driver/toggle-online', payload);

    if (response.success && response.user) {
      await this.saveUser(response.user);
      return response.user;
    }

    throw new Error(response.message || 'Failed to toggle online status');
  }

  async refreshUser() {
    const response = await ApiService.get('/driver/profile');

    if (response.success && response.user) {
      await this.saveUser(response.user);
      return response.user;
    }

    throw new Error(response.message || 'Failed to refresh user data');
  }
}

export default new AuthService();
