import AuthService from '../../services/auth';
import LocationService from '../../services/location';

let userRef = { current: null };

const state = {
  user: null,
  token: null,
  isLoading: true,
};

const getters = {
  isAuthenticated: (s) => !!s.token && !!s.user,
};

const mutations = {
  SET_USER(state, user) {
    state.user = user;
    userRef.current = user;
  },
  SET_TOKEN(state, token) {
    state.token = token;
  },
  SET_LOADING(state, v) {
    state.isLoading = v;
  },
};

const actions = {
  async initializeAuth({ commit, dispatch }) {
    try {
      const { token, user } = await AuthService.initializeAuth();
      commit('SET_TOKEN', token);
      commit('SET_USER', user);
    } catch (error) {
      console.error('Error initializing auth:', error);
    } finally {
      commit('SET_LOADING', false);
    }
    await dispatch('syncLocationLoop');
  },

  syncLocationLoop({ state, getters }) {
    if (!getters.isAuthenticated || !state.user) {
      try {
        LocationService.stopLocationUpdates();
      } catch (e) {
        console.error(e);
      }
      return;
    }
    if (state.user.isOnline) {
      try {
        LocationService.startLocationUpdates(
          () => LocationService.getCurrentLocation(),
          () => userRef.current && userRef.current.isOnline
        );
        console.log('Location updates started (user is online)');
      } catch (error) {
        console.error('Error starting location updates:', error);
      }
    } else {
      try {
        LocationService.stopLocationUpdates();
        console.log('Location updates stopped (user is offline)');
      } catch (error) {
        console.error('Error stopping location updates:', error);
      }
    }
  },

  async register({ commit, dispatch }, data) {
    try {
      const { user, token } = await AuthService.register(data);
      commit('SET_USER', user);
      commit('SET_TOKEN', token);
      dispatch('syncLocationLoop');
    } catch (error) {
      throw new Error(error.message || 'Registration failed');
    }
  },

  async login({ commit, dispatch }, data) {
    try {
      const { user: loggedInUser, token } = await AuthService.login(data);
      console.log('Login successful, user data from API:', loggedInUser);

      try {
        const refreshedUser = await AuthService.refreshUser();
        console.log('User profile refreshed:', refreshedUser);
        commit('SET_USER', refreshedUser);
      } catch (refreshError) {
        console.warn('Error refreshing user profile, using login response:', refreshError);
        commit('SET_USER', loggedInUser);
      }

      commit('SET_TOKEN', token);
      dispatch('syncLocationLoop');
    } catch (error) {
      throw new Error(error.message || 'Login failed');
    }
  },

  async logout({ commit, dispatch }) {
    try {
      await AuthService.logout();
      commit('SET_USER', null);
      commit('SET_TOKEN', null);
    } catch (error) {
      console.error('Logout error:', error);
      commit('SET_USER', null);
      commit('SET_TOKEN', null);
    } finally {
      try {
        LocationService.stopLocationUpdates();
      } catch (e) {
        console.error(e);
      }
    }
  },

  async toggleOnlineStatus({ commit, dispatch, state }, { latitude, longitude } = {}) {
    try {
      const updatedUser = await AuthService.toggleOnlineStatus(latitude, longitude);
      commit('SET_USER', { ...state.user, ...updatedUser });
      dispatch('syncLocationLoop');
    } catch (error) {
      throw new Error(error.message || 'Failed to toggle online status');
    }
  },

  async refreshUser({ commit, dispatch }) {
    try {
      const updatedUser = await AuthService.refreshUser();
      commit('SET_USER', updatedUser);
      dispatch('syncLocationLoop');
    } catch (error) {
      throw new Error(error.message || 'Failed to refresh user data');
    }
  },
};

export default {
  namespaced: true,
  state,
  getters,
  mutations,
  actions,
};
