<template>
  <div id="app-root">
    <router-view />
  </div>
</template>

<script>
function isEditableField(node) {
  if (!node || !node.closest) return false;
  return Boolean(
    node.closest('input, textarea, select, [contenteditable="true"]')
  );
}

export default {
  name: 'App',
  mounted() {
    this._onCopyCut = (e) => {
      if (!isEditableField(e.target)) {
        e.preventDefault();
      }
    };
    document.addEventListener('copy', this._onCopyCut, true);
    document.addEventListener('cut', this._onCopyCut, true);
  },
  beforeDestroy() {
    document.removeEventListener('copy', this._onCopyCut, true);
    document.removeEventListener('cut', this._onCopyCut, true);
  },
};
</script>

<style>
html,
body,
#app {
  height: 100%;
  margin: 0;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

#app-root {
  min-height: 100%;
}

input,
textarea,
select,
[contenteditable='true'] {
  -webkit-user-select: text;
  user-select: text;
}
</style>
