/**
 * Location Service — browser Geolocation API (mirrors RN behavior for web)
 */

import ApiService from './api';

const LOCATION_INTERVAL_MS = 30000;

class LocationService {
  constructor() {
    this.isUpdating = false;
    this.isConfigured = false;
    this.updateInterval = null;
    this.getLocationFn = null;
    this.isOnlineFn = null;
  }

  configure() {
    if (this.isConfigured) return;
    this.isConfigured = true;
  }

  startLocationUpdates(getCurrentLocation, isUserOnline) {
    try {
      if (!getCurrentLocation || typeof getCurrentLocation !== 'function') {
        console.error('getCurrentLocation is not a valid function');
        return;
      }
      if (!isUserOnline || typeof isUserOnline !== 'function') {
        console.error('isUserOnline is not a valid function');
        return;
      }

      this.stopLocationUpdates();
      this.getLocationFn = getCurrentLocation;
      this.isOnlineFn = isUserOnline;

      try {
        if (isUserOnline()) {
          this.updateLocationToBackend(getCurrentLocation, isUserOnline).catch(
            (error) => {
              console.error('Error in initial location update:', error);
            }
          );
        }
      } catch (error) {
        console.error('Error checking online status on start:', error);
      }

      this.updateInterval = setInterval(() => {
        const getLoc = this.getLocationFn;
        const online = this.isOnlineFn;
        if (!getLoc || !online) return;
        try {
          if (!online()) return;
        } catch {
          return;
        }
        this.updateLocationToBackend(getLoc, online).catch((error) => {
          console.error('Error in periodic location update:', error);
        });
      }, LOCATION_INTERVAL_MS);
    } catch (error) {
      console.error('Error starting location updates:', error);
    }
  }

  stopLocationUpdates() {
    if (this.updateInterval) {
      clearInterval(this.updateInterval);
      this.updateInterval = null;
    }
    this.getLocationFn = null;
    this.isOnlineFn = null;
  }

  async updateLocationToBackend(getCurrentLocation, isUserOnline) {
    if (this.isUpdating) return;

    if (!isUserOnline || typeof isUserOnline !== 'function') {
      console.error('isUserOnline function is not valid');
      return;
    }

    try {
      if (!isUserOnline()) {
        console.log('User is offline, skipping location update');
        return;
      }
    } catch (error) {
      console.error('Error checking online status:', error);
      return;
    }

    try {
      this.isUpdating = true;

      if (!getCurrentLocation || typeof getCurrentLocation !== 'function') {
        console.error('getCurrentLocation is not a valid function');
        this.isUpdating = false;
        return;
      }

      const location = await getCurrentLocation();

      if (!location) {
        console.warn('No location available to update');
        return;
      }

      try {
        if (!isUserOnline()) {
          console.log('User went offline during location fetch, skipping update');
          return;
        }
      } catch (error) {
        console.error('Error checking online status before update:', error);
        return;
      }

      const response = await ApiService.put('/driver/location', {
        latitude: location.latitude,
        longitude: location.longitude,
        isOnline: true,
      });

      if (response.success) {
        console.log('Location updated successfully:', location);
      } else {
        console.error('Failed to update location:', response.message);
      }
    } catch (error) {
      console.error('Error updating location to backend:', error);
    } finally {
      this.isUpdating = false;
    }
  }

  /**
   * Request one-shot browser geolocation
   */
  async getCurrentLocation() {
    this.configure();

    if (!navigator.geolocation) {
      console.warn('Geolocation not supported');
      return null;
    }

    return new Promise((resolve) => {
      navigator.geolocation.getCurrentPosition(
        (position) => {
          resolve({
            latitude: position.coords.latitude,
            longitude: position.coords.longitude,
          });
        },
        () => {
          resolve(null);
        },
        {
          enableHighAccuracy: true,
          timeout: 30000,
          maximumAge: 10000,
        }
      );
    });
  }
}

export default new LocationService();
